 * paginate(items, { page, perPage, sortKey })
 * Contract:
 *   - page is 1-indexed; page 1 is the first perPage items
 *   - out-of-range page => { items: [], hasNext: false, hasPrev: page > 1 }
 *   - sortKey, when given, sorts ascending by that key before paginating
 *   - hasNext/hasPrev reflect whether a next/previous page exists
 *   - total is always the full collection length
 */
export function paginate(items, { page = 1, perPage = 10, sortKey = null } = {}) {
  const source = sortKey ? [...items].sort(compareBy(sortKey)) : items;

  // Guard against degenerate input so a bad page/perPage cannot loop forever.
  const p = Math.max(1, Math.floor(page) || 1);
  const size = Math.max(1, Math.floor(perPage) || 1);

  // Half-open [start, end) window for this page — no off-by-one.
  const start = (p - 1) * size;
  const end = Math.min(start + size, source.length);

  const pageItems = start >= source.length ? [] : source.slice(start, end);

  return {
    items: pageItems,
    page: p,
    perPage: size,
    total: source.length,
    hasPrev: p > 1,
    hasNext: end < source.length,
  };
}

function compareBy(sortKey) {
  return (a, b) => {
    const av = a[sortKey];
    const bv = b[sortKey];
    if (av === bv) return 0;
    if (av === undefined || av === null) return 1; // missing values sort last
    if (bv === undefined || bv === null) return -1;
    return av < bv ? -1 : 1;
  };
}

